import streamlit as st
import requests
import pandas as pd

API_URL = "http://127.0.0.1:8000"

st.set_page_config(page_title="FounderIQ AI", layout="wide")

st.title("🚀 FounderIQ AI Dashboard")

try:
    response = requests.get(f"{API_URL}/dashboard")
    data = response.json()

    col1, col2, col3 = st.columns(3)

    col1.metric("Total Deals", data["totalDeals"])
    col2.metric("Deal Owners", len(data["dealOwners"]))
    col3.metric("Pipeline Stages", len(data["salesPipeline"]))

    st.divider()

    st.subheader("Deals")

    df = pd.DataFrame(data["deals"])

    if not df.empty:
        st.dataframe(df, use_container_width=True)
    else:
        st.info("No deals found.")

except Exception as e:
    st.error(e)